const chat = $input.first().json;
return [{json: {...chat, config: {
  model: 'qwen3.5:9b', evaluation_model: 'qwen3.5:9b',
  proxy_url: 'http://token-proxy:8003', langfuse_url: 'http://langfuse-web:3000',
  evaluate: true, capture_content: false
}}}];

const id = String($execution.id);
if (!/^\d+$/.test(id)) throw new Error('Execution ID inválido');
return $input.all().map((item,index) => ({json:{...item.json,
token_tracking:{execution_id:id,correlation_id:`${id}-${index}`,model:item.json.config.model}}}));

const original = $('Tokens - Identificar Execução').first().json;
const config = original.config;
const output = String($input.first().json.output ?? '');
const crypto = require('crypto');
const trace_id = crypto.randomBytes(16).toString('hex');
const span_id = crypto.randomBytes(8).toString('hex');
const start = Number($('Iniciar Cronômetro IA').first().json.inicio_ia_ms);
const end = Date.now();
function sanitize(s) {
  return String(s ?? '').replace(/[\w.+-]+@[\w.-]+\.[a-z]{2,}/gi,'[EMAIL]')
    .replace(/\b\d{3}\.?\d{3}\.?\d{3}-?\d{2}\b/g,'[CPF]')
    .replace(/(?:\+?55[ .-]?)?\(?\d{2}\)?[ .-]?9\d{4}[ .-]?\d{4}/g,'[TELEFONE]')
    .replace(/Bearer\s+[^\s]+/gi,'[TOKEN]')
    .replace(/(?:sk|pk)-[A-Za-z0-9_-]+/g,'[CHAVE]').slice(0,4000);
}
const session_id = crypto.createHash('sha256').update(String(original.sessionId ?? $execution.id)).digest('hex');
const attr = (key,value) => ({key,value:{stringValue:String(value)}});
const attributes = [
  attr('langfuse.observation.type','agent'),attr('langfuse.trace.name','n8n-ollama-observability'),
  attr('langfuse.session.id',session_id),attr('langfuse.environment','local-demo'),
  attr('langfuse.observation.input',JSON.stringify(config.capture_content ? sanitize(original.chatInput) : '[CONTEÚDO OMITIDO]')),
  attr('langfuse.observation.output',JSON.stringify(config.capture_content ? sanitize(output) : '[CONTEÚDO OMITIDO]')),
  attr('langfuse.observation.metadata.execution_id',$execution.id)
];
const span = {traceId:trace_id,spanId:span_id,name:'Agente IA',kind:1,
  startTimeUnixNano:String(BigInt(start)*1000000n),endTimeUnixNano:String(BigInt(end)*1000000n),attributes};
return [{json:{output,config,trace_id,span_id,session_id,execution_id:String($execution.id),
  correlation_id:original.token_tracking.correlation_id,start_ms:start,end_ms:end,duracao_ms:end-start,
  otlp:{resourceSpans:[{resource:{attributes:[attr('service.name','n8n-ollama-observability')]},scopeSpans:[{scope:{name:'n8n-langfuse'},spans:[span]}]}]}}}];

const original = $('Langfuse - Preparar Trace').first().json;
const usage = $input.first().json;
const otlp = JSON.parse(JSON.stringify(original.otlp));
const spans = otlp.resourceSpans[0].scopeSpans[0].spans;
const attr=(key,value)=>({key,value:{stringValue:String(value)}});
let status = 'unavailable';
if (usage.status === 'real' && usage.correlation_id === original.correlation_id && Array.isArray(usage.records) && usage.records.length) {
  const ids = new Set(); let input=0,output=0;
  for (const r of usage.records) {
    if (!r.request_id || ids.has(r.request_id) || r.status !== 'real' ||
      !Number.isSafeInteger(r.input_tokens) || !Number.isSafeInteger(r.output_tokens) ||
      r.input_tokens<0 || r.output_tokens<0 || r.total_tokens!==r.input_tokens+r.output_tokens)
      throw new Error('Contadores reais inválidos');
    ids.add(r.request_id); input+=r.input_tokens;output+=r.output_tokens;
    // One observation per actual request: avoids double counting parent totals.
    spans.push({traceId:original.trace_id,spanId:require('crypto').randomBytes(8).toString('hex'),parentSpanId:original.span_id,
      name:'Ollama — geração',kind:1,startTimeUnixNano:String(BigInt(original.start_ms)*1000000n),
      endTimeUnixNano:String(BigInt(original.end_ms)*1000000n),attributes:[
        attr('langfuse.observation.type','generation'),attr('langfuse.session.id',original.session_id),
        attr('langfuse.trace.name','n8n-ollama-observability'),attr('langfuse.observation.model.name',r.model),
        attr('langfuse.observation.usage_details',JSON.stringify({input:r.input_tokens,output:r.output_tokens,total:r.total_tokens})),
        attr('langfuse.observation.metadata.usage_source','real'),attr('langfuse.observation.metadata.request_id',r.request_id),
        {key:'gen_ai.usage.input_tokens',value:{intValue:String(r.input_tokens)}},
        {key:'gen_ai.usage.output_tokens',value:{intValue:String(r.output_tokens)}}]});
  }
  if(input!==usage.input_tokens || output!==usage.output_tokens || input+output!==usage.total_tokens || ids.size!==usage.requests)
    throw new Error('Agregação inconsistente');
  status='real';
}
spans[0].attributes.push(attr('langfuse.observation.metadata.token_status',status));
return [{json:{...original,otlp,token_status:status}}];

try {
function extrairObjetos(texto) {
  const objetos = [];
  let inicio = -1;
  let nivel = 0;
  let emString = false;
  let escape = false;

  for (let i = 0; i < texto.length; i++) {
    const caractere = texto[i];

    if (nivel === 0) {
      if (caractere === "{") {
        inicio = i;
        nivel = 1;
        emString = false;
        escape = false;
      }
      continue;
    }

    if (emString) {
      if (escape) {
        escape = false;
      } else if (caractere.charCodeAt(0) === 92) {
        escape = true;
      } else if (caractere === '"') {
        emString = false;
      }
      continue;
    }

    if (caractere === '"') emString = true;
    if (caractere === "{") nivel++;

    if (caractere === "}") {
      nivel--;

      if (nivel === 0) {
        try {
          objetos.push(JSON.parse(texto.slice(inicio, i + 1)));
        } catch {
          // Trecho entre chaves não é JSON válido.
        }
      }
    }
  }

  return objetos;
}

return $input.all().map((item, index) => {
  const entrada = item.json;
  let resultado;

  // Aceita também uma entrada que já seja o objeto esperado.
  if (Object.hasOwn(entrada, "score")) {
    resultado = entrada;
  } else {
    if (typeof entrada.text !== "string" || !entrada.text.trim()) {
      throw new Error(
        `Item ${index + 1}: campo "text" ausente ou vazio. ` +
        `Campos recebidos: ${Object.keys(entrada).join(", ")}`
      );
    }

    // Desconsidera raciocínio delimitado, quando presente.
    const texto = entrada.text
      .replace(/<think\b[^>]*>[\s\S]*?<\/think>/gi, "")
      .trim();

    resultado = extrairObjetos(texto)
      .filter(objeto => Object.hasOwn(objeto, "score"))
      .at(-1);
  }

  if (!resultado) {
    throw new Error(
      `Item ${index + 1}: nenhum objeto JSON com "score" foi encontrado.`
    );
  }

  const { score, justificativa } = resultado;

  if (
    typeof score !== "number" ||
    !Number.isFinite(score) ||
    score < 0 ||
    score > 1
  ) {
    throw new Error(
      `Item ${index + 1}: "score" deve ser um número entre 0 e 1.`
    );
  }

  if (typeof justificativa !== "string" || !justificativa.trim()) {
    throw new Error(
      `Item ${index + 1}: "justificativa" deve ser um texto não vazio.`
    );
  }

  return {
    json: { score, justificativa },
    pairedItem: { item: index }
  };
});

} catch { return [{json:{evaluation_status:"unavailable"}}]; }

